#!/usr/bin/env node
// Generates the single-file standalone build (index.js) from src/.
//
// The hosting panel this bot runs on takes one uploaded file, so the modular
// source has to be flattened. Rather than renaming everything into one scope,
// this emits a tiny CommonJS registry: each source file keeps its own module
// scope and its own `require`, so the flattened build behaves exactly like the
// modular tree and name collisions are impossible.
//
// Usage: node build-bundle.js [outputPath]

const fs = require('fs');
const path = require('path');

const ROOT = __dirname;
const OUT = process.argv[2] ?? path.join(ROOT, 'dist', 'index.js');

function walk(dir, out = []) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(full, out);
    else if (entry.name.endsWith('.js')) out.push(full);
  }
  return out;
}

const toKey = (file) => path.relative(ROOT, file).replace(/\\/g, '/').replace(/\.js$/, '');

const sourceFiles = walk(path.join(ROOT, 'src'));
const entryFile = path.join(ROOT, 'index.js');

// Handlers discover their modules with fs.readdirSync at runtime, which cannot
// work once flattened. They are replaced with static equivalents built from the
// same directory listings at build time.
const HANDLER_KEYS = new Set(['src/handlers/commandHandler', 'src/handlers/prefixCommandHandler', 'src/handlers/eventHandler']);

const listKeys = (subdir) =>
  fs
    .readdirSync(path.join(ROOT, 'src', subdir))
    .filter((f) => f.endsWith('.js'))
    .sort()
    .map((f) => `src/${subdir}/${f.replace(/\.js$/, '')}`);

function staticHandler(key) {
  if (key === 'src/handlers/commandHandler') {
    const requires = listKeys('commands').map((k) => `  require('${k}'),`).join('\n');
    return `const defs = [\n${requires}\n];

module.exports = function loadCommands(client) {
  client.commands = new Map();
  for (const command of defs) {
    if (command?.data && command?.execute) client.commands.set(command.data.name, command);
    else console.warn('[WARN] A command is missing "data" or "execute" and was skipped.');
  }
  console.log(\`Loaded \${client.commands.size} commands.\`);
};
`;
  }

  if (key === 'src/handlers/prefixCommandHandler') {
    const requires = listKeys('prefixCommands').map((k) => `  require('${k}'),`).join('\n');
    return `const modules = [\n${requires}\n];

module.exports = function loadPrefixCommands(client) {
  client.prefixCommands = new Map();
  client.prefixCommandList = [];

  for (const exported of modules) {
    const commands = Array.isArray(exported) ? exported : [exported];
    for (const command of commands) {
      if (!command?.name || !command?.execute) {
        console.warn('[WARN] A prefix command is missing "name" or "execute" and was skipped.');
        continue;
      }
      client.prefixCommands.set(command.name, command);
      for (const alias of command.aliases ?? []) client.prefixCommands.set(alias, command);
      client.prefixCommandList.push(command);
    }
  }

  console.log(\`Loaded \${client.prefixCommandList.length} prefix commands (\${client.prefixCommands.size} with aliases).\`);
};
`;
  }

  const requires = listKeys('events').map((k) => `  require('${k}'),`).join('\n');
  return `const events = [\n${requires}\n];

module.exports = function loadEvents(client) {
  for (const event of events) {
    if (event.once) client.once(event.name, (...args) => event.execute(...args, client));
    else client.on(event.name, (...args) => event.execute(...args, client));
  }
  console.log(\`Loaded \${events.length} events.\`);
};
`;
}

// Rewrites relative specifiers to registry keys so the emitted `require` can
// resolve them. Anything non-relative (discord.js, fs, ...) is left alone and
// falls through to Node's real require at runtime.
function rewriteRequires(code, fromFile) {
  return code.replace(/require\((['"])(\.[^'"]*)\1\)/g, (match, quote, specifier) => {
    const resolved = path.resolve(path.dirname(fromFile), specifier);
    const candidates = [resolved, `${resolved}.js`, path.join(resolved, 'index.js')];
    const target = candidates.find((c) => fs.existsSync(c) && fs.statSync(c).isFile());
    if (!target) throw new Error(`Cannot resolve ${specifier} from ${path.relative(ROOT, fromFile)}`);
    return `require('${toKey(target)}')`;
  });
}

const chunks = [];

chunks.push(`// Boat Bot — standalone single-file build.
// Generated by build-bundle.js from the modular source. Do not edit by hand:
// change src/ and re-run \`npm run build\`.

'use strict';

// Minimal CommonJS registry. Each module below keeps its own scope, so the
// flattened build resolves names exactly like the modular tree does.
const __modules = {};
const __cache = {};

function __require(id) {
  if (Object.prototype.hasOwnProperty.call(__cache, id)) return __cache[id].exports;
  const factory = __modules[id];
  // Not one of ours — hand it to Node (discord.js, better-sqlite3, fs, ...).
  if (!factory) return require(id);

  const module = { exports: {} };
  __cache[id] = module;
  factory(module, module.exports, __require);
  return module.exports;
}
`);

for (const file of [...sourceFiles, entryFile]) {
  const key = toKey(file);
  let code;

  if (HANDLER_KEYS.has(key)) {
    code = staticHandler(key);
  } else {
    code = rewriteRequires(fs.readFileSync(file, 'utf8'), file);

    // The bundle sits next to its own data directory rather than two levels up.
    if (key === 'src/config/db') {
      const before = code;
      code = code.replace("path.join(__dirname, '..', '..', 'data')", "path.join(__dirname, 'data')");
      if (code === before) throw new Error('db.js DATA_DIR rewrite did not apply — check the path expression.');
    }

    // The entry needs to expose the client so the epilogue can hook ready.
    if (key === 'index') code += '\nmodule.exports = { client };\n';
  }

  chunks.push(`__modules[${JSON.stringify(key)}] = function (module, exports, require) {\n${code}\n};\n`);
}

// Standalone builds have no separate deploy step, so slash commands are
// registered on ready using the application's own id.
chunks.push(`// ---- standalone entry ----

const { REST, Routes } = require('discord.js');

const __app = __require('index');

async function __deploySlashCommands(client) {
  const rest = new REST({ version: '10' }).setToken(process.env.DISCORD_TOKEN);
  const body = [...client.commands.values()].map((command) => command.data.toJSON());
  try {
    // If a command is ever deployed to BOTH the global scope and a specific
    // guild, Discord shows it twice in that guild's slash-command picker —
    // two separate entries with the same name, each independently
    // clickable. That's the usual cause of "it ran twice" for a single
    // click. This bot deploys on every restart, so clearing the global
    // scope first guarantees a leftover registration from an earlier
    // GUILD_ID setting (or lack of one) can never coexist with the current
    // one — self-healing on every startup, not just a one-time fix.
    await rest.put(Routes.applicationCommands(client.application.id), { body: [] }).catch(() => {});

    if (process.env.CLEANUP_GUILD_ID && process.env.CLEANUP_GUILD_ID !== process.env.GUILD_ID) {
      await rest.put(Routes.applicationGuildCommands(client.application.id, process.env.CLEANUP_GUILD_ID), { body: [] }).catch(() => {});
    }

    const route = process.env.GUILD_ID
      ? Routes.applicationGuildCommands(client.application.id, process.env.GUILD_ID)
      : Routes.applicationCommands(client.application.id);
    console.log(\`Deploying \${body.length} slash commands\${process.env.GUILD_ID ? \` to guild \${process.env.GUILD_ID}\` : ' globally'}...\`);
    await rest.put(route, { body });
    console.log('Slash commands deployed successfully.');
  } catch (error) {
    console.error('Failed to deploy commands:', error);
  }
}

__app.client.once('ready', () => {
  __deploySlashCommands(__app.client).catch((error) => console.error('Slash command deploy error:', error));
});
`);

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, chunks.join('\n'));

const lines = chunks.join('\n').split('\n').length;
console.log(`Built ${path.relative(process.cwd(), OUT)} — ${sourceFiles.length + 1} modules, ${lines} lines.`);
